// Who attacks, and which pitch slots take part on each side
local AtkTeamId = [0];
local AtkNum = [0];
local AtkParamId = [0, 0, 0];
local DefNum = [0];
local DefParamId = [0, 0, 0];
CMND_BTL_GET_CALC_PARAM(1, AtkTeamId, AtkNum, AtkParamId, DefNum, DefParamId);

// The command each team chose: [POW, DIFF, FAUL, ATTR, NUM]
local AtkCmndParam = [0, 0, 0, 0, 0];
CMND_BTL_GET_CALC_PARAM(3, AtkTeamId[0], AtkCmndParam);
local DefCmndParam = [0, 0, 0, 0, 0];
CMND_BTL_GET_CALC_PARAM(3, AtkTeamId[0] ^ 1, DefCmndParam);

// The lead attacker's eight stats, then each attacker's element
local AtkPlayerParam = [0, 0, 0, 0, 0, 0, 0, 0];
local AtkElement = [[5], [5], [5]];
CMND_BTL_GET_CALC_PARAM(2, AtkParamId[0], AtkPlayerParam);
for( local i = 0; i < AtkNum[0]; i++ )
{
	CMND_BTL_GET_CALC_PARAM(4, AtkParamId[i], AtkElement[i]);
}

// 0 unless the lead attacker's Fighting Spirit is out
local AtkKeshinPower = [0];
CMND_BTL_GET_CALC_PARAM(8, AtkParamId[0], AtkTeamId[0], AtkKeshinPower);

// Is the objective's character leading the attack or the defence?
local atkPPsBns = [0];
local defPPsBns = [0];
CMND_BTL_GET_CALC_PARAM(9, atkPPsBns, defPPsBns);

CalFinalRevision <- function ( teamId, AtkParamId = 0, DefParamId = 0 )
{
	local subTeamLv = [0];
	CMND_BTL_GET_CALC_PARAM(10, teamId, true, AtkParamId, DefParamId, subTeamLv);

	// Not lower than the other side: no change
	if (subTeamLv[0] >= 0)
	{
		return 1.0;
	}

	// Lower: the further below, the weaker (down to 0.2)
	local sub = -subTeamLv[0];
	if (sub > 30)
	{
		return 0.2;
	}
	return 0.00079999998 * sub * sub - 0.0517 * sub + 1.0;
};
